def zfeat(k):
    z = (rm-mrm)@Vt[:k].T
    if k==0: return np.ones((N,1))
    idx = [(a,b) for a in range(k) for b in range(a,k)]
    F = [z, np.column_stack([z[:,a]*z[:,b] for a,b in idx])]
    return np.hstack([np.ones((N,1))]+F)
